 document.body.insertAdjacentHTML('beforeend',`<section id="team-chat" aria-label="Team chat"><div id="chat-history"></div><form id="chat-form" hidden><label for="chat-input">TEAM</label><input id="chat-input" maxlength="200" autocomplete="off" placeholder="Message your team…"></form></section>`);
 function drawChat(){const now=Date.now();$('chat-history').replaceChildren(...messages.filter(m=>historyOpen||now-m.at<9000).slice(historyOpen?-12:-3).map(m=>{const line=document.createElement('p'),who=document.createElement('strong'),body=document.createElement('span');who.textContent=m.name+': ';who.style.color='#'+Number(m.color).toString(16).padStart(6,'0');body.textContent=m.text;line.append(who,body);line.style.opacity=historyOpen?'1':String(Math.min(1,(9000-(now-m.at))/2000));return line;}));}
